"/* =====================================================================
   AssetFlow Style System (Vanilla CSS with Premium Design)
   Supports Light/Dark Mode, Glassmorphism, Micro-animations & Mobile-first
   ===================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Kanit:wght@300;400;500;600;700&family=Sarabun:wght@300;400;500;600;700&display=swap');

:root {
    /* Font Families */
    --font-heading: 'Kanit', sans-serif;
    --font-body: 'Sarabun', sans-serif;

    /* Theme Transition */
    --transition-speed: 0.3s;
    --ease-curve: cubic-bezier(0.4, 0, 0.2, 1);

    /* Light Theme Variables */
    --bg-primary: #f8fafc;
    --bg-secondary: #ffffff;
    --bg-tertiary: #f1f5f9;
    --text-primary: #0f172a;
    --text-secondary: #475569;
    --text-tertiary: #94a3b8;
    --border-color: #e2e8f0;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
    --glass-bg: rgba(255, 255, 255, 0.7);
    --glass-border: rgba(255, 255, 255, 0.5);

    /* Accents (Common) */
    --color-primary: #3b82f6;        /* Bright Blue */
    --color-primary-hover: #2563eb;
    --color-secondary: #8b5cf6;      /* Vibrant Purple */
    --color-secondary-hover: #7c3aed;
    --color-accent: #06b6d4;         /* Cyan */

    /* Status Colors */
    --status-normal: #10b981;        /* Emerald Green */
    --status-normal-bg: rgba(16, 185, 129, 0.15);
    --status-damaged: #f59e0b;       /* Amber Orange */
    --status-damaged-bg: rgba(245, 158, 11, 0.15);
    --status-lost: #ef4444;          /* Rose Red */
    --status-lost-bg: rgba(239, 68, 68, 0.15);
    --status-pending: #64748b;       /* Slate Grey */
    --status-pending-bg: rgba(100, 116, 139, 0.15);
}

