     */
    normalizeAssetNumber(str) {
        if (!str) return '';
        // 1. ลบช่องว่างทั้งหมดออก
        let cleaned = str.replace(/\s+/g, '');
        // 2. แปลงตัวอักษรที่มักสับสนกลับเป็นตัวเลข
        cleaned = cleaned.replace(/[Oo]/g, '0');
        cleaned = cleaned.replace(/[Iil|]/g, '1');
        return cleaned.toUpperCase();
    }

